 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Isolate 4-connected objects and move each object to the corresponding
    # opposite-color object's bounding-box location; preserve its local form.
    comps, seen = [], set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx)); stack.append((yy, xx))
            comps.append((color, cells))
    if len(comps) != 4:
        return [row[:] for row in grid]
    def box(cells):
        return (min(y for y,x in cells), min(x for y,x in cells),
                max(y for y,x in cells), max(x for y,x in cells))
    # In these examples the two objects of each color exchange positions,
    # swapping color as well: each pair retains their respective shapes.
    out = [[0]*w for _ in range(h)]
    for i, (color, cells) in enumerate(comps):
        same_color = [j for j,(co,_) in enumerate(comps) if co == color and j != i]
        if not same_color:
            continue
        j = same_color[0]
        # objects at matching locations? Move to same-color partner's box.
        target = box(comps[j][1])
        sy0,sx0,sy1,sx1 = box(cells); ty0,tx0,_,_ = target
        for y,x in cells:
            yy,xx = ty0 + y-sy0, tx0 + x-sx0
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
    return out
