    # the nearest object of the other color, preserving its cell geometry.
    h, w = len(grid), len(grid[0])
    objs, seen = [], set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objs.append((color,cells))
    if len(objs) != 4:
        return [row[:] for row in grid]
    def center(cells):
        return (sum(y for y,x in cells)/len(cells), sum(x for y,x in cells)/len(cells))
    def box(cells):
        return min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells)
    out=[[0]*w for _ in range(h)]
    # Each same-position pair of unlike objects trades places.
    unused=set(range(4)); pairs=[]
    while unused:
        i=min(unused); ci=center(objs[i][1])
        j=min((k for k in unused if k!=i), key=lambda k: abs(center(objs[k][1])[0]-ci[0])+abs(center(objs[k][1])[1]-ci[1]))
        unused.remove(i); unused.remove(j); pairs.append((i,j))
    for i,j in pairs:
