            sy,sx,ey,ex=box(src); ty,tx,_,_=box(dst)
            for y,x in src:
                yy,xx=ty+(y-sy),tx+(x-sx)
                if 0<=yy<h and 0<=xx<w: out[yy][xx]=col
    return out
