                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color, cells))
    # The pieces arrange in two horizontal bands based on their source x-position:
    # left-origin pieces go into the upper band, right-origin pieces into the lower.
    out = [[0]*w for _ in range(h)]
