 "content": "def transform(grid):
    # Arrange the four color objects into the 2x2 pattern seen in the demos:
    # the two colors switch their diagonal positions, retaining object shape.
    h, w = len(grid), len(grid[0])
    comps, seen = [], set()
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if not col or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                y, x = stack.pop(); cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == col and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((col, cells))
    # Main diagonal components exchange upper/lower slots; anti-diagonal
    # components also exchange slots. Place objects in their same columns.
    out = [[0]*w for _ in range(h)]
    for col, cells in comps:
        y0, x0 = min(y for y,x in cells), min(x for y,x in cells)
        y1, x1 = max(y for y,x in cells), max(x for y,x in cells)
        upper = (y0+y1)/2 < h/2
        left = (x0+x1)/2 < w/2
        # The output keeps left/right halves, exchanging the object's vertical slot.
        target_y = 7 if upper else 4
        target_x = 0 if left else 5
        for y,x in cells:
            yy,xx = target_y + (y-y0), target_x + (x-x0)
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = col
    return out

