                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))

    groups = {}
    for color, cells in comps:
        groups.setdefault(color, []).append(cells)

    # The two object colors alternate in the output's two lower rows of stacks.
    # Main-diagonal pair goes left; anti-diagonal pair goes right.
    def bounds(cells):
        return min(y for y,x in cells), min(x for y,x in cells), max(y for y,x in cells), max(x for y,x in cells)
    def main_diag(pair):
        b = [bounds(c) for c in pair]
        return (b[0][0]+b[0][2]-b[1][0]-b[1][2]) * (b[0][1]+b[0][3]-b[1][1]-b[1][3]) > 0
