        pair = sorted(pair, key=lambda cells: bounds(cells)[0], reverse=True)
        for slot, cells in enumerate(pair):
            y0,x0,y1,x1 = bounds(cells)
            # two fixed destination bands: top at rows 4-6, bottom at rows 7-9
            band_top, band_bottom = ((4,6) if slot == 0 else (7,9))
            height = y1-y0+1
            ty = band_bottom-height+1
            for y,x in cells:
                yy,xx = ty+y-y0, xbase+x-x0
                if 0 <= yy < h and 0 <= xx < w:
